SELECT c.guid,c.name,c.account,a.username,c.race,c.class,c.level,c.online,COALESCE(ev.add_value,0),COALESCE(ev.add_validIn,0),COALESCE(ev.login_value,0),IF(gm.memberGuid IS NULL,0,1),COALESCE(GROUP_CONCAT(CONCAT(cs.skill,':',cs.value,'/',cs.max) ORDER BY cs.skill SEPARATOR ','),'NONE') FROM tw_char.characters c JOIN tw_logon.account a ON a.id=c.account JOIN (SELECT bot,MAX(IF(event='add',value,0)) add_value,MAX(IF(event='add',validIn,0)) add_validIn,MAX(IF(event='login',value,0)) login_value FROM tw_char.ai_playerbot_random_bots WHERE owner=0 GROUP BY bot) ev ON ev.bot=c.guid LEFT JOIN tw_char.group_member gm ON gm.memberGuid=c.guid LEFT JOIN tw_char.character_skills cs ON cs.guid=c.guid AND cs.skill IN (164,165,171,182,186,197,202,333,393) WHERE a.username LIKE 'RNDBOT%' AND c.online=0 AND ev.add_value=1 AND ev.login_value=0 AND gm.memberGuid IS NULL GROUP BY c.guid,c.name,c.account,a.username,c.race,c.class,c.level,c.online,ev.add_value,ev.add_validIn,ev.login_value,gm.memberGuid ORDER BY COUNT(cs.skill) DESC,c.level DESC,c.guid LIMIT 25;